import sys, json, time, random, base64, zlib, io, math
from collections import Counter
import numpy as np

BLOB = ""
RANKS = "23456789TJQKA"; SUITS = "shdc"
RV = {r: i + 2 for i, r in enumerate(RANKS)}
def cint(s): return RANKS.index(s[0]) * 4 + SUITS.index(s[1])
def cstr(c): return RANKS[c >> 2] + SUITS[c & 3]

# ------------------------------------------------------------------ vectorized evaluator
_B = 14
def _tables():
    hi = np.zeros(8192, np.int64); st = np.zeros(8192, np.int64)
    for m in range(1, 8192):
        hi[m] = m.bit_length(); best = 0
        for h in range(12, 3, -1):
            if all(m & (1 << (h - k)) for k in range(5)): best = h + 1; break
        if best == 0 and (m & 15) == 15 and (m & (1 << 12)): best = 4
        st[m] = best
    return hi, st
HI, STR = _tables(); POW2 = (1 << np.arange(13)).astype(np.int64); AR13 = np.arange(13)
def _bit(d): return (np.ones_like(d) << d) >> 1
def _top(mask, k):
    out = np.zeros_like(mask)
    for i in range(5):
        if i < k:
            d = HI[mask]; mask = mask ^ _bit(d); out = out * _B + d
        else: out = out * _B
    return out
def evaluate7(cards):
    r = cards >> 2; s = cards & 3
    oh = (r[:, :, None] == AR13[None, None, :]); cn = oh.sum(axis=1)
    m1 = ((cn >= 1) * POW2).sum(1); m2 = ((cn >= 2) * POW2).sum(1)
    m3 = ((cn >= 3) * POW2).sum(1); m4 = ((cn >= 4) * POW2).sum(1)
    fm = np.zeros(len(cards), dtype=np.int64)
    for su in range(4):
        sm = ((s == su)[:, :, None] & oh).any(axis=1)
        fm = np.where((s == su).sum(1) >= 5, (sm * POW2).sum(1), fm)
    S, B = _B ** 5, _B
    best = _top(m1, 5)
    p = HI[m2]; best = np.where(p > 0, S + p * B**4 + _top(m1 & ~_bit(p), 3) // B, best)
    p2 = HI[m2 & ~_bit(p)]; kk = HI[m1 & ~_bit(p) & ~_bit(p2)]
    best = np.where(p2 > 0, 2 * S + p * B**4 + p2 * B**3 + kk * B**2, best)
    t = HI[m3]; best = np.where(t > 0, 3 * S + t * B**4 + _top(m1 & ~_bit(t), 2) // B, best)
    st = STR[m1]; best = np.where(st > 0, 4 * S + st * B**4, best)
    best = np.where(fm > 0, 5 * S + _top(fm, 5), best)
    fp = HI[m2 & ~_bit(t)]; best = np.where((t > 0) & (fp > 0), 6 * S + t * B**4 + fp * B**3, best)
    q = HI[m4]; best = np.where(q > 0, 7 * S + q * B**4 + HI[m1 & ~_bit(q)] * B**3, best)
    sf = STR[fm]; return np.where(sf > 0, 8 * S + sf * B**4, best)

# ------------------------------------------------------------------ rank5 discard heuristic (stdlib)
def rank5(cards):
    values = sorted((RV[c[0]] for c in cards), reverse=True)
    flush = len({c[1] for c in cards}) == 1
    uniq = sorted(set(values), reverse=True); sh = 0
    if len(uniq) == 5:
        if uniq[0] - uniq[4] == 4: sh = uniq[0]
        elif uniq == [14, 5, 4, 3, 2]: sh = 5
    groups = sorted(Counter(values).items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    shape = [n for _, n in groups]; bg = tuple(v for v, _ in groups)
    if sh and flush: return (8, sh)
    if shape == [4, 1]: return (7,) + bg
    if shape == [3, 2]: return (6,) + bg
    if flush: return (5,) + tuple(values)
    if sh: return (4, sh)
    if shape == [3, 1, 1]: return (3,) + bg
    if shape == [2, 2, 1]: return (2,) + bg
    if shape == [2, 1, 1, 1]: return (1,) + bg
    return (0,) + tuple(values)
_BASE = (0.20, 0.50, 0.70, 0.78, 0.84, 0.88, 0.95, 0.98, 0.99)
def _p_hit(outs, unseen=47):
    if outs <= 0: return 0.0
    return 1 - ((unseen - outs) / unseen) * ((unseen - 1 - outs) / (unseen - 1))
def _est(keep, flop):
    cards = list(keep) + list(flop); r = rank5(cards); cat = r[0]
    made = _BASE[cat] + 0.05 * (r[1] - 2) / 12 + (0.01 * (r[2] - 2) / 12 if len(r) > 2 else 0.0)
    if cat >= 4: return made
    suits = Counter(c[1] for c in cards); ks = Counter(c[1] for c in keep)
    fouts = 9 if any(n == 4 and ks[s] >= 1 for s, n in suits.items()) else 0
    bd = 0.035 if any(n == 3 and ks[s] == 2 for s, n in suits.items()) else 0.0
    ranks = {RV[c[0]] for c in cards}; kr = {RV[c[0]] for c in keep}
    if 14 in ranks: ranks.add(1)
    if 14 in kr: kr.add(1)
    sr = set()
    for x in range(1, 15):
        if x in ranks: continue
        for lo in range(max(1, x - 4), min(x, 10) + 1):
            w = set(range(lo, lo + 5))
            if x in w and (w - {x}) <= ranks and (w & kr): sr.add(14 if x == 1 else x); break
    outs = 4 * len(sr) + (fouts - len(sr) if fouts else 0)
    return min(0.92, made + (1 - made) * (_p_hit(outs) * 0.7 + bd))
def heuristic_discard(hole, flop):
    sc = []
    for d in range(3):
        keep = [c for i, c in enumerate(hole) if i != d]
        sc.append((_est(keep, flop), -RV[hole[d][0]], hole[d]))
    sc.sort(reverse=True)
    return sc[0][2], sc[0][0] - sc[1][0]

# ------------------------------------------------------------------ preflop tree + table
STACK = 200
class Node: pass
def _targets(nr, bo, last_inc, p):
    t = [5, 8] if (nr == 1 and p == 0) else [6, 10] if (nr == 1 and p == 1) else \
        [3 * bo, STACK] if nr == 2 else [int(round(2.2 * bo)), STACK] if nr == 3 else []
    lo, out = bo + max(last_inc, 2), []
    for x in t:
        x = min(x, STACK)
        if (x >= lo or x == STACK) and x > bo and x not in out: out.append(x)
    return out
def build_tree():
    nodes = []
    def mk(**kw):
        n = Node(); n.__dict__.update(kw); n.id = len(nodes); nodes.append(n); return n
    def rec(b, p, nr, last_inc):
        bo, bp = b[1 - p], b[p]; acts, kids = [], []
        if bo > bp:
            acts.append("f"); kids.append(mk(kind="fold", player=p, bet=bp)); acts.append("c")
            kids.append(rec([2, 2], 1, 1, 0) if (p == 0 and bp == 1 and nr == 1) else mk(kind="call", bet=bo))
        else:
            acts.append("x"); kids.append(mk(kind="call", bet=bo))
        for tgt in _targets(nr, bo, last_inc, p):
            nb = list(b); nb[p] = tgt; acts.append("r%d" % tgt); kids.append(rec(nb, 1 - p, nr + 1, tgt - bo))
        return mk(kind="act", player=p, actions=acts, children=kids, bo=bo)
    return rec([1, 2], 0, 1, 2)
ROOT = build_tree()
_D = np.load(io.BytesIO(zlib.decompress(base64.b64decode(BLOB))))
TRI = _D["tri"].astype(np.int64)
STRAT = {int(k[1:]): _D[k] for k in _D.files if k.startswith("n")}

def pf_decide(req, st):
    """Walk the solved preflop tree along the actual history; return (action, amount) or None."""
    seat0 = st["seat"] == "button"
    node = ROOT
    for h in req["history"]:
        if h["street"] != "preflop": continue
        if node.kind != "act": return None
        if (node.player == 0) != (seat0 == (h["actor"] == "me")): return None
        a = h["action"]
        if a == "fold": key = "f"
        elif a == "check": key = "x"
        elif a == "call": key = "c"
        else:
            amt = h.get("amount", 0); best = None
            for i, act in enumerate(node.actions):
                if act[0] == "r":
                    d = abs(math.log(max(1, int(act[1:])) / max(1, amt)))
                    if best is None or d < best[0]: best = (d, i)
            if best is None: return None
            node = node.children[best[1]]; continue
        if key not in node.actions: return None
        node = node.children[node.actions.index(key)]
    if node.kind != "act" or (node.player == 0) != seat0: return None
    cls = int(TRI[st["hole_int"][0] * 2704 + st["hole_int"][1] * 52 + st["hole_int"][2]])
    p = STRAT[node.id][cls].astype(np.float64); p = p / p.sum() if p.sum() > 0 else np.ones(len(p)) / len(p)
    k = int(np.random.choice(len(p), p=p)); act = node.actions[k]
    legal = req["legal_actions"]; tc = req["to_call"]
    if act == "f": return ("fold", 0) if "fold" in legal else ("check", 0)
    if act == "c": return ("call", 0) if "call" in legal else ("check", 0)
    if act == "x": return ("check", 0) if "check" in legal else ("call", 0)
    if "raise" not in legal: return ("call", 0) if "call" in legal else ("check", 0)
    tgt = int(act[1:])
    if tgt >= STACK: amt = req["max_raise"]
    else:
        scale = req["opp_bet"] / max(1, node.bo)
        amt = int(round(tgt * scale))
    return ("raise", max(req["min_raise"], min(req["max_raise"], amt)))

# ------------------------------------------------------------------ Monte Carlo equity
DECK = np.arange(52)
RATE = {"per_ms": 400.0}                     # evaluations per ms, calibrated at startup
def calibrate():
    x = np.array([random.sample(range(52), 7) for _ in range(6000)])
    evaluate7(x[:500]); t = time.perf_counter(); evaluate7(x); dt = (time.perf_counter() - t) * 1000
    RATE["per_ms"] = max(50.0, 6000 / max(dt, 0.5))

def equity(keeps, board, dead, T, q=1.0):
    """keeps: list of 2-card int lists (shared samples).

    The villain's card count tracks the street. Before the discard (3 board cards)
    it holds 3 and commits to a keep from the flop alone - it cannot see the runout
    any more than we can - and from the turn on it holds 2. Modelling it as a flat
    2-card hand pre-discard while hero takes max over 3 keeps inflated hero's flop
    equity by ~11 points on average and ~20 when hero is paired (393k-situation GPU
    run, symmetry-gated), because the option value was granted to one side only."""
    used = set(board) | set(dead) | {c for k in keeps for c in k}
    unseen = np.array([c for c in range(52) if c not in used])
    n = len(unseen); miss = 5 - len(board)
    nv = 3 if len(board) == 3 else 2                  # villain hole cards on this street
    idx = np.argsort(np.random.random((T, n)), axis=1)[:, :nv + miss]; g = unseen[idx]
    bb = np.broadcast_to(np.array(board, dtype=np.int64), (T, len(board)))
    bd = np.concatenate([bb, g[:, nv:]], 1)
    need_cur = q < 0.999
    if nv == 2:
        so = evaluate7(np.concatenate([g[:, :2], bd], 1))
        cur = evaluate7(np.concatenate([g[:, :2], bb], 1)) if need_cur else None
    else:
        vks = np.stack([g[:, [a for a in range(3) if a != d]] for d in range(3)], 0)   # (3,T,2)
        pre = np.stack([evaluate7(np.concatenate([vks[d], bb], 1)) for d in range(3)], 0)
        vk = vks[pre.argmax(0), np.arange(T)]         # villain's committed keep
        so = evaluate7(np.concatenate([vk, bd], 1))
        cur = pre.max(0) if need_cur else None        # its strength now, reused for the range filter
    if not need_cur: w = np.ones(T)
    else:   # opponent range = top share by CURRENT made-hand strength, plus a random slice for draws/bluffs
        core = cur >= np.quantile(cur, 1 - 0.8 * q)
        extra = (~core) & (np.random.random(T) < 0.2 * q / max(1e-9, 1 - 0.8 * q))
        w = (core | extra).astype(np.float64)
        if w.sum() < 20: w = np.ones(T)
    out = []
    for kp in keeps:
        sm = evaluate7(np.concatenate([np.broadcast_to(np.array(kp, dtype=np.int64), (T, 2)), bd], 1))
        out.append(float((((sm > so) + 0.5 * (sm == so)) * w).sum() / w.sum()))
    return out

# ------------------------------------------------------------------ opponent model
class Stats:
    def __init__(self):
        self.c = Counter()
    def update(self, history):
        pend = None; street = None
        for h in history:
            if h["street"] == "preflop": continue
            if h["street"] != street: street, pend = h["street"], None
            a, who = h["action"], h["actor"]
            if who == "opp":
                if pend == "me":
                    self.c["faced_n"] += 1
                    self.c["fold" if a == "fold" else "raise_resp" if a == "raise" else "call_resp"] += 1
                else:
                    self.c["open_n"] += 1; self.c["open_bet" if a == "raise" else "open_chk"] += 1
            if a == "raise": pend = who
            elif a in ("call", "fold"): pend = None
    def fold_rate(self): return (self.c["fold"] + 2) / (self.c["faced_n"] + 5)
    def agg(self): return (self.c["open_bet"] + self.c["raise_resp"] + 2) / (self.c["open_n"] + self.c["faced_n"] + 6)

# ------------------------------------------------------------------ bot state & decisions
class Bot:
    def __init__(self):
        self.stats = Stats(); self.total = 400; self.left = 60000; self.hand = 0
        self.st = {}; self.last_q = 1.0; self.cost = {}; self.bank0 = 60000
    def budget_T(self, nk, share=0.25):
        """Monte Carlo sample count from the measured cost per sample; plans to leave ~40% of the bank unspent."""
        if self.left < 6000: return 0
        hands_left = max(1, self.total - self.hand + 1)
        ms = max(0.0, (self.left - (0.4 * self.bank0 + 3500)) / hands_left) * share
        per = self.cost.get(nk, (nk + (4 if nk == 3 else 2)) / RATE["per_ms"])
        return int(max(150, min(5000, ms / per)))

    def timed_equity(self, keeps, board, dead, T, q):
        t0 = time.perf_counter(); r = equity(keeps, board, dead, T, q)
        per = (time.perf_counter() - t0) * 1000 / T; nk = len(keeps)
        self.cost[nk] = per if nk not in self.cost else 0.7 * self.cost[nk] + 0.3 * per
        return r

    def opp_range_q(self, req):
        tc = req["to_call"]
        if tc <= 0: return 0.9
        f = tc / max(1, req["pot"] - tc)
        q = 0.55 if f <= 0.4 else 0.42 if f <= 0.8 else 0.32 if f <= 1.5 else 0.22
        nr = sum(1 for h in req["history"] if h["street"] == req["street"] and h["actor"] == "opp" and h["action"] == "raise")
        if nr >= 2: q *= 0.7
        a = self.stats.agg()
        q *= 1.5 if a > 0.5 else 0.8 if a < 0.2 else 1.0
        return max(0.1, min(1.0, q))

    def hero_keeps(self):
        h = self.st["hole_int"]
        if len(h) == 3: return [[h[i] for i in range(3) if i != d] for d in range(3)]
        return [list(h)]

    def safe(self, req):
        legal = req["legal_actions"]
        if "check" in legal: return ("check", 0)
        if "call" in legal and req["to_call"] <= max(2, 0.12 * req["pot"]): return ("call", 0)
        return ("fold", 0)

    def act(self, req):
        self.left = req["time_left_ms"]
        if req["street"] == "preflop":
            r = pf_decide(req, self.st)
            return r if r else self.safe(req)
        return self.postflop(req)

    def raise_to(self, req, frac):
        pot, tc = req["pot"], req["to_call"]
        amt = req["opp_bet"] + int(frac * (pot + tc)) if tc > 0 else req["my_bet"] + int(frac * pot)
        amt = max(req["min_raise"], min(req["max_raise"], amt))
        if amt >= 0.55 * (req["my_stack"] + req["my_bet"]) and amt < req["max_raise"] and req["max_raise"] - amt < 0.35 * req["max_raise"]:
            amt = req["max_raise"]
        return ("raise", amt)

    def postflop(self, req):
        legal = req["legal_actions"]
        T = self.budget_T(len(self.hero_keeps()))
        if T == 0: return self.heuristic_play(req)
        q = self.opp_range_q(req); self.last_q = q
        eqs = self.timed_equity(self.hero_keeps(), [cint(c) for c in req["board"]], self.st["dead"], T, q)
        eq = max(eqs); pot, tc = req["pot"], req["to_call"]
        st = self.stats; fr = st.fold_rate(); river = req["street"] == "river"
        if tc > 0:
            odds = tc / (pot + tc); margin = 0.03 + (0.04 if tc > 0.6 * pot else 0.0)
            if "raise" in legal and eq > 0.80 and random.random() < 0.8: return self.raise_to(req, 0.7)
            if eq > odds + margin: return ("call", 0) if "call" in legal else ("check", 0)
            return ("fold", 0) if "fold" in legal else ("check", 0)
        if "raise" not in legal: return ("check", 0)
        if eq > 0.68: return self.raise_to(req, 0.75 if eq > 0.82 else 0.6)
        if eq > 0.55 and random.random() < 0.7: return self.raise_to(req, 0.45)
        if not river and 0.25 < eq < 0.5 and random.random() < 0.18 + 0.4 * max(0, fr - 0.4): return self.raise_to(req, 0.6)
        if river and eq < 0.2 and fr > 0.45 and random.random() < 0.25: return self.raise_to(req, 0.6)
        return ("check", 0)

    def heuristic_play(self, req):
        legal = req["legal_actions"]
        if req["to_call"] == 0: return ("check", 0)
        if req["to_call"] <= 0.25 * req["pot"] and "call" in legal: return ("call", 0)
        return ("fold", 0)

    def discard(self, req):
        self.left = req["time_left_ms"]
        hole = req["hole_cards"]; board = req["board"]
        h_card, margin = heuristic_discard(hole, board)
        T = self.budget_T(3, share=0.35)
        if T == 0 or margin >= 0.30: return h_card
        hi = [cint(c) for c in hole]
        keeps = [[hi[i] for i in range(3) if i != d] for d in range(3)]
        eqs = self.timed_equity(keeps, [cint(c) for c in board], [], T, max(0.4, self.last_q))
        best = int(np.argmax(eqs)); order = sorted(range(3), key=lambda d: -eqs[d])
        if eqs[order[0]] - eqs[order[1]] < 0.004: return h_card if eqs[hole.index(h_card)] >= eqs[order[0]] - 0.004 else hole[best]
        return hole[best]

def main():
    bot = Bot(); calibrate()
    for line in sys.stdin:
        line = line.strip()
        if not line: continue
        try: msg = json.loads(line)
        except ValueError: continue
        t = msg.get("type"); reply = None
        try:
            if t == "init":
                bot.total = msg.get("total_hands", 400); bot.left = bot.bank0 = msg.get("time_bank_ms", 60000)
            elif t == "new_hand":
                bot.hand = msg["hand_id"]; bot.last_q = 1.0
                bot.st = {"seat": msg["seat"], "hole": msg["hole_cards"], "hole_int": [cint(c) for c in msg["hole_cards"]], "dead": []}
            elif t == "action_request":
                a, amt = bot.act(msg)
                reply = {"type": "action", "action": a}
                if a == "raise": reply["amount"] = int(amt)
            elif t == "discard_request":
                reply = {"type": "discard", "card": bot.discard(msg)}
            elif t == "discard_result":
                bot.st["hole"] = msg["hole_cards"]; bot.st["hole_int"] = [cint(c) for c in msg["hole_cards"]]
                bot.st["dead"] = [cint(msg["my_discard"]), cint(msg["opp_discard"])]
            elif t == "hand_result":
                bot.stats.update(msg.get("history", []))
            elif t == "match_end":
                break
        except Exception as e:
            print("error:", repr(e), file=sys.stderr)
            if t == "action_request":
                try: a, amt = bot.safe(msg)
                except Exception: a = "fold" if "fold" in msg.get("legal_actions", []) else "check"; amt = 0
                reply = {"type": "action", "action": a}
            elif t == "discard_request":
                try: reply = {"type": "discard", "card": min(msg["hole_cards"], key=lambda c: RV[c[0]])}
                except Exception: reply = {"type": "discard", "card": msg["hole_cards"][0]}
        if reply is not None:
            print(json.dumps(reply), flush=True)

if __name__ == "__main__":
    main()
